package http

import (
	_ "embed"
	"net/http"
)

// The API document, generated by protoc-gen-openapiv2 from the same
// google.api.http annotations that generate the REST routes.
//
// Embedded rather than read from disk, so the binary carries its own
// documentation and a container has nothing to mount. And served from the
// gateway rather than published separately, because a spec that lives anywhere
// else is a spec that describes an older version of this.
//
//go:embed openapi.json
var document []byte

func OpenAPI() http.HandlerFunc {
	return func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		// Public: it describes the shape of the API, not its data, and a client
		// generating from it should not need a token first.
		w.Header().Set("Cache-Control", "public, max-age=300")
		_, _ = w.Write(document)
	}
}
